2	
3	/**
4	 * Resolve a writable directory for server-side persistence (analytics, LLM
5	 * cache, etc.).
6	 *
7	 * On Vercel Functions only `/tmp` is writable, and it lives only as long as
8	 * the warm container — so persistence does not survive cold starts. In dev
9	 * and self-hosted deployments we write to the repo's `data/` dir for durable
10	 * cross-restart storage.
11	 */
12	export function dataDir(...subpaths: string[]): string {
13	  const base = process.env.VERCEL ? "/tmp" : join(process.cwd(), "data");
14	  return subpaths.length > 0 ? join(base, ...subpaths) : base;
15	}
